import{_ as o,a0 as p,w as l,s as d,I as s,x as t,a1 as a,A as n,ao as r}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"掌握强大的 Git 变基命令 | LCTT x X-CMD","titleTemplate":false,"description":"掌握强大的 Git 变基命令 | LCTT (202212) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"掌握强大的 Git 变基命令 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"掌握强大的 Git 变基命令 | LCTT (202212) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202212/20221121.2 ⭐️⭐️ Learn Git 3 commands to level up your skill","title":"掌握强大的 Git 变基命令","tag":"202212","desc":""},"relativePath":"202212/20221121.2 ⭐️⭐️ Learn Git 3 commands to level up your skill.md","filePath":"[post].md"}'),c={name:"202212/20221121.2 ⭐️⭐️ Learn Git 3 commands to level up your skill.md"};function g(u,e,b,m,h,k){const i=p("Link");return l(),d("div",null,[e[26]||(e[26]=s("h1",{id:"掌握强大的-git-变基命令",tabindex:"-1"},[t("掌握强大的 Git 变基命令 "),s("a",{class:"header-anchor",href:"#掌握强大的-git-变基命令","aria-label":"Permalink to “掌握强大的 Git 变基命令”"},"​")],-1)),e[27]||(e[27]=s("p",null,[s("img",{src:"https://img.linux.net.cn/data/attachment/album/202212/07/133637yq2526zsp7f1t7a2.jpg",alt:""})],-1)),e[28]||(e[28]=s("blockquote",null,[s("p",null,"学习如何使用 Git 来压扁、变基和精选。")],-1)),s("p",null,[e[1]||(e[1]=t("当我与别人谈到 Git 时，几乎每个人都对 ",-1)),a(i,{href:"https://opensource.com/article/20/4/git-rebase-i"},{default:n(()=>[...e[0]||(e[0]=[t("git rebase 命令",-1)])]),_:1}),e[2]||(e[2]=t(" 有强烈的印象，这个命令让许多人遇到了问题，而不得不更改目录、删除仓库、然后再重新克隆一个仓库。我认为这是因为他们误解了分支是如何工作，遇到了一个非常糟糕的默认界面，还有一些合并冲突把事情搞得一团糟。",-1))]),e[29]||(e[29]=r(`<h3 id="怎么找不到-git-squash-命令" tabindex="-1">怎么找不到 git squash 命令？ <a class="header-anchor" href="#怎么找不到-git-squash-命令" aria-label="Permalink to “怎么找不到 git squash 命令？”">​</a></h3><p>如果你曾在本地的仓库提交过很多次，并希望能把这些提交都合并为一个提交，接下来，我们就来介绍能用什么 Git 命令达到这个目的。Git 称这个概念为 “<ruby>压扁提交<rt> squash commits </rt></ruby>”。我在编写文档时发现了这个概念：我花了十几个提交才修改好我的 Markdown 文档，但是仓库的维护者不想看到我的所有尝试，以免扰乱了该项目的历史，所以我被告知“需要压扁你的提交”。</p><p><strong>压扁提交</strong>听起来是一个很有用的方法。但是只有一个问题：我不知道该怎么做。作为 Git 的新手，我做了任何人会做的事情：我去查阅 <code>git-squash</code> 的手册，但我立即遇到了阻碍：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ man git-squash</span></span>
<span class="line"><span>&gt; No manual entry for git-squash</span></span></code></pre></div>`,4)),s("p",null,[e[4]||(e[4]=t("我发现没有一个名为 ",-1)),e[5]||(e[5]=s("code",null,"squash",-1)),e[6]||(e[6]=t(" 的 Git 命令，而是被要求 ",-1)),a(i,{href:"https://opensource.com/article/22/4/manage-git-commits-rebase-i-command"},{default:n(()=>[...e[3]||(e[3]=[t("运行一个完全独立的命令：git rebase 命令",-1)])]),_:1}),e[7]||(e[7]=t("，该命令能将我的所有提交最终合并为一个提交。",-1))]),e[30]||(e[30]=r(`<p>我知道我碰到一个常见的情形：已经使用工具一段时间的人使用了<strong>行话</strong>或引用了一个概念，这个概念对他们来说是非常清楚的，但对新手来说就不能明白了。从概念上讲，这个情况看起来是这样的：</p><p><img src="https://opensource.com/sites/default/files/2022-11/gitbeyond2.spices.png" alt="Image of 6 bowls of different colored spices, and an arrow pointing to the second image of all the spices blended into one bowl."></p><p>我这样说是为了鼓励你，你绝对不是第一个或最后一个 <em>被 Git 或谈论 Git 的人</em> 弄糊涂的人。你可以要求对方说明白他的意见，并帮助你应该使用的正确命令。仓库的维护者实际上的意思是，“使用 <code>git rebase</code> 命令**，将很多提交压扁成一个提交”。</p><h3 id="现在就来学习-git-rebase-命令吧" tabindex="-1">现在就来学习 git rebase 命令吧 <a class="header-anchor" href="#现在就来学习-git-rebase-命令吧" aria-label="Permalink to “现在就来学习 git rebase 命令吧”">​</a></h3><p><code>git rebase</code> 命令会将一个提交链从其第一个父级中删除，并将其放置在另一个提交链的末尾，将两个提交链组合成一个长链，而不是两个并行链。我意识到这是一个很复杂的定义。</p><p>回想一下 Git 的提交是如何链接在一起的，你可以看到，除了初始的 <code>main</code>（或 <code>master</code>）分支外，任何分支都有一个 <ruby>父提交<rt> parent commit </rt></ruby> 作为该链的 “<ruby>基础<rt> base </rt></ruby>”。“<ruby>变基<rt> rebase </rt></ruby>” 能使另一个链中的最后一个提交成为指定分支的新 “<ruby>基础提交<rt> base commit </rt></ruby>”。</p><p>在 Git 中整合来自不同分支的修改主要有两种方法：<ruby>合并<rt>merge</rt></ruby> 以及 <ruby>变基<rt>rebase</rt></ruby>，你可能更熟悉 <code>git merge</code> 命令。接下来，就来看看 [git-scm.com] 是如何解释 <code>git merge</code> 和 <code>git rebase</code> 的差异：</p><p><img src="https://opensource.com/sites/default/files/2022-11/gitbeyond2.gitmerger.png" alt="Image of Git merge versus git rebase shown as numbered bubbles."></p><p>在合并示例中，它会把两个分支的最新快照（<code>C3</code> 和 <code>C4</code>）以及二者最近的共同祖先（<code>C2</code>）进行三方合并，合并的结果是生成一个新的快照（<code>C5</code>）。<code>experiment</code> 的分支指针仍然存在，仍然指向 <code>C4</code>。</p><p>在变基示例中，它提取在 <code>C4</code> 中引入的补丁和修改，然后在 <code>C3</code> 的基础上应用一次，使 <code>C3</code> 成为 <code>C4</code> 的新父级，并产生了一个名为 <code>C4&#39;</code> 的新提交。</p><p>（LCTT 译注：具体的命令如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git checkout experiment</span></span>
<span class="line"><span>$ git rebase main</span></span>
<span class="line"><span>First, rewinding head to replay your work on top of it...</span></span>
<span class="line"><span>Applying: added staged command</span></span></code></pre></div><p>它的原理是首先找到这两个分支 —— 即当前分支 <code>experiment</code>、变基操作的目标基底分支 <code>main</code> —— 的最近共同祖先 <code>C2</code>，然后对比当前分支相对于该祖先的历次提交，提取相应的修改并存为临时文件，然后将当前分支指向目标基底 <code>C3</code>，最后以此将之前另存为临时文件的修改依序应用。）</p><p>值得注意的是，分支指针 <code>main</code> 没有移动。要让 Git 将指针移动到链的末尾（由<code>experiment</code> 指向），你还需要执行合并。</p><p>（LCTT 译注：具体的命令如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git checkout main</span></span>
<span class="line"><span>$ git merge experiment</span></span></code></pre></div><p><img src="https://www.progit.cn/images/basic-rebase-4.png" alt="master 分支的快进合并"></p><p>此时，<code>C4&#39;</code> 指向的快照就和上面使用 <code>merge</code> 命令的例子中 <code>C5</code> 指向的快照一模一样了。）</p><p><code>git rebase</code> 并不能替代 <code>git merge</code>。<code>git rebase</code> 是一种用于制作更清晰的历史记录，以与 <code>git merge</code> 结合使用的工具。</p><p>（LCTT 译注：使用 <code>git rebase</code> 命令将提交到某一分支上的所有修改都移至另一分支上，就好像“重新播放”一样。）</p><h4 id="交互式变基能给你一个更友好的界面" tabindex="-1">交互式变基能给你一个更友好的界面！ <a class="header-anchor" href="#交互式变基能给你一个更友好的界面" aria-label="Permalink to “交互式变基能给你一个更友好的界面！”">​</a></h4><p>从命令行执行 <code>git rebase</code> 命令，最可怕的地方在于它<strong>糟糕的默认界面</strong>。运行命令 <code>git rebase &lt;target-refr&gt;</code> 要么有效，要么会变得一团糟，因为它没有太多的反馈或方法来确保它做你想做的事情。幸运的是，<code>git rebase</code> 命令和许多其他 Git 命令一样，具有 <ruby>交互模式<rt> interactive mode </rt></ruby>，你可以使用参数 <code>-i</code> 或者 <code>-interactive</code> 来使用交互模式。</p><p><img src="https://opensource.com/sites/default/files/2022-11/gitbeyond2.GitLens%20Interactive%20Rebase%20tool%20in%20VS%20Code.png" alt="Image of the Git lens interactive Rebase tool in VS Code."></p><p>在使用交互式模式时，<code>git rebase</code> 会从一个糟糕的黑框界面转换为一个<strong>选项菜单</strong>，允许你选择对正在变基的提交链所做的事。对于每个提交，你可以<strong>选择</strong>：</p><ul><li><ruby>选用<rt>pick</rt></ruby>：按原样包含</li><li><ruby>重写<rt>reword</rt></ruby>：重写提交消息</li><li><ruby>编写<rt>edit</rt></ruby>：在变基完成之前对提交中的文件进行进一步更改</li><li><ruby>压扁<rt>squash</rt></ruby>：将多个提交压缩成一个提交，保留所有提交消息</li><li><ruby>修理<rt>fixup</rt></ruby>：将多个提交压缩成一个提交，但只保留最后一个提交消息</li><li><ruby>丢弃<rt>drop</rt></ruby>：丢弃此提交</li></ul>`,25)),s("p",null,[e[9]||(e[9]=t("就我个人而言，我更喜欢 ",-1)),a(i,{href:"https://marketplace.visualstudio.com/items?itemName=eamodio.gitlens"},{default:n(()=>[...e[8]||(e[8]=[t("VS Code 的开源 GitLens 扩展",-1)])]),_:1}),e[10]||(e[10]=t(" 使用下拉选择列表布局选项的方式，但 Git 允许你使用任何编辑器选择这些选项。对于 Emacs 或 Vim 等纯文本工具，你需要键入选择，而不是从菜单中选择，但最终结果仍然是相同的。",-1))]),e[31]||(e[31]=r(`<h4 id="何时做变基" tabindex="-1">何时做变基 <a class="header-anchor" href="#何时做变基" aria-label="Permalink to “何时做变基”">​</a></h4><p>知道 <em>何时</em> 做变基与知道 <em>如何</em> 做变基同样重要。事实上，如果你不在乎你的仓库历史提交消息有点混乱的话，那么你可以永远都不使用 <code>git rebase</code> 命令。但是，如果你想要更干净的历史提交消息，并且想要更少扰乱你的图形视图的提交，那么当你使用 <code>git rebase</code> 命令时，有一个重要的<strong>经验法则</strong>需要时刻记住：</p><blockquote><p>“不要变基你存储库以外的的提交，那些提交可能是别人工作的基础。”</p></blockquote><p>如果你遵循该准则，不会发生什么大问题的。</p><p>简而言之，如果你让一个<strong>本地分支</strong>来完成你的工作，变基是没有问题的。但一旦该分支被 <ruby>推送 <rt> push </rt></ruby> 了，就不要再变基该分支了。当然，你想要怎么做完全取决于你自己。</p><p>希望你会认为上述内容有助于你理解 <code>git rebase</code> 命令的工作原理，并能让你更有信心地使用它。与任何 Git 命令一样，<strong>练习</strong>是学习和理解怎么做的唯一方法。我鼓励你勇敢地尝试 <ruby>交互式变基<rt> interactive rebase </rt></ruby> <code>git rebase -i &lt;branch name&gt;</code>！</p><h3 id="接下来学习-git-cherry-pick-命令吧" tabindex="-1">接下来学习 Git cherry-pick 命令吧 <a class="header-anchor" href="#接下来学习-git-cherry-pick-命令吧" aria-label="Permalink to “接下来学习 Git cherry-pick 命令吧”">​</a></h3><p>大多数开发人员将修改提交到某一分支上，但是之后发现他们一直<strong>提交到了错误的分支上</strong>。理想情况下，他们可以拿走那个提交，然后把它移到正确的分支，这正是 <code>git cherry-pick</code> 命令的作用。</p><p><code>git cherry-pick</code> 命令利用了变基单个提交的方法。这一用法非常常见，以至于有了它自己的命令。</p><p><img src="https://opensource.com/sites/default/files/2022-11/gitbeyond2.cherrypicking.png" alt="Image of a woman picking a cherry from one tree and putting on another tree."></p><p>要使用 <code>git cherry-pick</code>，你只需告诉 Git 你要移动到“那个分支”的提交 ID（由 <code>HEAD</code> 指向）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git cherry-pick &lt;target-ref&gt;</span></span></code></pre></div><p>如果出现问题，你可以根据 Git 提供的错误消息，来进行恢复：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git cherry-pick -i 2bc01cd</span></span>
<span class="line"><span>Auto-merging README.md</span></span>
<span class="line"><span>CONFLICT (content): Merge conflict in README.md</span></span>
<span class="line"><span>error: could not apply 2bc01cd… added EOF lines</span></span>
<span class="line"><span>hint: After resolving the conflicts, mark them with</span></span>
<span class="line"><span>hint: &quot;git add/rm &quot;, then run</span></span>
<span class="line"><span>hint: &quot;git cherry-pick --continue&quot;.</span></span>
<span class="line"><span>hint: You can instead skip this commit with &quot;git cherry-pick --skip&quot;.</span></span>
<span class="line"><span>hint: To abort and get back to the state before &quot;git cherry-pick&quot;,</span></span>
<span class="line"><span>hint: run &quot;git cherry-pick --abort&quot;.</span></span>
<span class="line"><span>$ git cherry-pick --abort</span></span></code></pre></div><h3 id="让-git-更强大" tabindex="-1">让 Git 更强大 <a class="header-anchor" href="#让-git-更强大" aria-label="Permalink to “让 Git 更强大”">​</a></h3><p><code>git rebase</code> 命令是 Git 实用程序强大的地方之一。你最好在测试仓库中先练习一下怎么使用，一旦你熟悉了它的概念和工作流程，你就可以给仓库一个清晰历史消息记录了。</p><hr>`,17)),s("p",null,[e[12]||(e[12]=t("via: ",-1)),a(i,{href:"https://opensource.com/article/22/11/advanced-git-commands"},{default:n(()=>[...e[11]||(e[11]=[t("https://opensource.com/article/22/11/advanced-git-commands",-1)])]),_:1})]),s("p",null,[e[17]||(e[17]=t("作者：",-1)),a(i,{href:"https://opensource.com/users/dwaynemcdaniel"},{default:n(()=>[...e[13]||(e[13]=[t("Dwayne McDaniel",-1)])]),_:1}),e[18]||(e[18]=t(" 选题：",-1)),a(i,{href:"https://github.com/lkxed"},{default:n(()=>[...e[14]||(e[14]=[t("lkxed",-1)])]),_:1}),e[19]||(e[19]=t(" 译者：",-1)),a(i,{href:"https://github.com/chai001125"},{default:n(()=>[...e[15]||(e[15]=[t("chai001125",-1)])]),_:1}),e[20]||(e[20]=t(" 校对：",-1)),a(i,{href:"https://github.com/wxy"},{default:n(()=>[...e[16]||(e[16]=[t("wxy",-1)])]),_:1})]),s("p",null,[e[23]||(e[23]=t("本文由 ",-1)),a(i,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...e[21]||(e[21]=[t("LCTT",-1)])]),_:1}),e[24]||(e[24]=t(" 原创编译，",-1)),a(i,{href:"https://linux.cn/"},{default:n(()=>[...e[22]||(e[22]=[t("Linux中国",-1)])]),_:1}),e[25]||(e[25]=t(" 荣誉推出",-1))])])}const T=o(c,[["render",g]]);export{C as __pageData,T as default};
